interface Button { render(): void }
interface Checkbox { render(): void }
interface UIFactory { createButton(): Button; createCheckbox(): Checkbox }
class LightFactory implements UIFactory { createButton(){ return new LightButton() } createCheckbox(){ return new LightCheckbox() } }
class DarkFactory implements UIFactory { createButton(){ return new DarkButton() } createCheckbox(){ return new DarkCheckbox() } }
function buildUI(factory: UIFactory){ return { btn: factory.createButton(), chk: factory.createCheckbox() } }

// Version A: registry of factory instances
interface Button { render(): void }
interface Checkbox { render(): void }
interface UIFactory { createButton(): Button; createCheckbox(): Checkbox }
const factoryRegistry = new Map<string, UIFactory>()
factoryRegistry.set('light', new LightFactory())
function createUI(theme: string){ const f = factoryRegistry.get(theme)!; return { btn: f.createButton(), chk: f.createCheckbox() } }

// Version B: single factory with conditionals
class MonolithicFactory { createButton(theme: string){ if(theme === 'light') return new LightButton(); return new DarkButton() } createCheckbox(theme: string){ if(theme === 'light') return new LightCheckbox(); return new DarkCheckbox() } }
